## 5. Backend Code (Express + Mongo)

**`server/index.js`**
```js
import express from "express";
import mongoose from "mongoose";
import cors from "cors";
import postsRouter from "./routes/posts.js";

const app = express();
app.use(cors());
app.use(express.json());

mongoose.connect(process.env.MONGO_URI)
  .then(() => console.log("DB connected"));

app.use("/api/posts", postsRouter);
app.listen(4000, () => console.log("Server on :4000"));
```

**`server/models/Post.js`**
```js
import mongoose from "mongoose";

const PostSchema = new mongoose.Schema({
  anonId: String,
  room: { type: String, default: "general" },
  body: { type: String, required: true, maxlength: 280 },
  reactions: { like: {type:Number,default:0}, laugh:{type:Number,default:0}, fire:{type:Number,default:0} },
  replyTo: { type: mongoose.Schema.Types.ObjectId, ref: "Post", default: null },
  expiresAt: Date,
  flagged: { type: Boolean, default: false },
}, { timestamps: true });

export default mongoose.model("Post", PostSchema);
```

**`server/routes/posts.js`**
```js
import express from "express";
import Post from "../models/Post.js";

const router = express.Router();

// list feed
router.get("/", async (req, res) => {
  const { room } = req.query;
  const filter = room ? { room } : {};
  const posts = await Post.find(filter).sort({ createdAt: -1 }).limit(50);
  res.json(posts);
});

// create post
router.post("/", async (req, res) => {
  const { anonId, body, room, burnHours } = req.body;
  const expiresAt = burnHours
    ? new Date(Date.now() + burnHours * 3600 * 1000)
    : null;
  const post = await Post.create({ anonId, body, room, expiresAt });
  res.json(post);
});

// react
router.post("/:id/react", async (req, res) => {
  const { type } = req.body; // "like" | "laugh" | "fire"
  const inc = {}; inc[`reactions.${type}`] = 1;
  const post = await Post.findByIdAndUpdate(
    req.params.id, { $inc: inc }, { new: true }
  );
  res.json(post);
});

// flag
router.post("/:id/flag", async (req, res) => {
  const post = await Post.findByIdAndUpdate(
    req.params.id, { flagged: true }, { new: true }
  );
  res.json(post);
});

export default router;
```

