const BASE = "http://localhost:4000/api/posts";

export const getPosts = (room) =>
  fetch(`${BASE}?room=${room || ""}`).then(r => r.json());

export const createPost = (data) =>
  fetch(BASE, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(data),
  }).then(r => r.json());

export const react = (id, type) =>
  fetch(`${BASE}/${id}/react`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ type }),
  }).then(r => r.json());
```

