import { useEffect, useState } from "react";
import { getPosts, createPost, react } from "./api";
import PostCard from "./components/PostCard";
import Composer from "./components/Composer";

export default function App() {
  const [posts, setPosts] = useState([]);
  const [room, setRoom] = useState("general");

  const anonId = localStorage.getItem("anonId") ||
    (() => { const id = crypto.randomUUID(); localStorage.setItem("anonId", id); return id; })();

  const load = () => getPosts(room).then(setPosts);
  useEffect(() => { load(); }, [room]);

  const handlePost = async (body, burnHours) => {
    await createPost({ anonId, body, room, burnHours });
    load();
  };

  const handleReact = async (id, type) => {
    await react(id, type);
    load();
  };

  return (
    <div className="max-w-xl mx-auto p-4">
      <h1 className="text-2xl font-bold mb-4">WhisperWall</h1>
      <Composer onSubmit={handlePost} />
      <div className="mt-6 space-y-3">
        {posts.map(p => (
          <PostCard key={p._id} post={p} onReact={handleReact} />
        ))}
      </div>
    </div>
  );
}
```

