import { useState } from "react";

export default function Composer({ onSubmit }) {
  const [body, setBody] = useState("");
  const [burn, setBurn] = useState(0);

  const submit = (e) => {
    e.preventDefault();
    if (!body.trim()) return;
    onSubmit(body, burn);
    setBody("");
  };

  return (
    <form onSubmit={submit} className="bg-white p-3 rounded-xl shadow">
      <textarea
        className="w-full resize-none outline-none"
        placeholder="Say something anonymously..."
        maxLength={280}
        value={body}
        onChange={e => setBody(e.target.value)}
      />
      <div className="flex justify-between items-center mt-2">
        <select value={burn} onChange={e => setBurn(+e.target.value)}
          className="text-sm border rounded px-2 py-1">
          <option value={0}>No burn</option>
          <option value={1}>Burn in 1h</option>
          <option value={24}>Burn in 24h</option>
        </select>
        <button className="bg-black text-white px-4 py-1 rounded-full text-sm">
          Post
        </button>
      </div>
    </form>
  );
}
```

